```go
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/apache/avro/go/avro"
)

// Struct represents the struct that we want to convert.
type Struct struct {
	Name string `json:"name"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run main.go <source_file> <struct_name>")
		return
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Read the struct definition from the source file
	file, err := os.Open(sourceFile)
	if err != nil {
		fmt.Printf("Error opening file %s: %v\n", sourceFile, err)
		return
	}
	defer file.Close()

	var structDef *Struct
	err = json.NewDecoder(file).Decode(&structDef)
	if err != nil {
		fmt.Printf("Failed to decode JSON into struct: %v\n", err)
		return
	}

	// Generate the Avro schema
	schema, err := avro.SchemaFromProto(Struct{}.MarshalBinary())
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	// Write the schema to a file
	outputPath := fmt.Sprintf("%s.avsc", structName)
	err = os.WriteFile(outputPath, schema.Marshal(), 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema to %s: %v\n", outputPath, err)
		return
	}

	fmt.Printf("Avro schema generated successfully at %s\n", outputPath)
}
```

### How to Use This Program:

1. Save this code into a file named `main.go`.
2. Create your Go source file (e.g., `example.go`) with a struct definition similar to the following:
   ```go
   package example

   type Person struct {
       Name string `json:"name"`
   }
   ```
3. Run the program using the command line:
   ```sh
   go run main.go example.go Person
   ```

This will read the `Person` struct from the `example.go` file, generate its Avro schema, and save it as `Person.avsc`. Make sure you have the necessary dependencies installed (`github.com/apache/avro/go/avro`), which can usually be done via `go get github.com/apache/avro/go/avro`.

The resulting Avro schema file will contain definitions for all fields within the struct, including their types and formats.

